from pathlib import Path
p=Path('outputs/Binocular.app/Contents/Resources')
# Original vector artwork: stadium roof, seating tiers, ribbon lights and marked turf.
seats=''.join(f'<ellipse cx="650" cy="190" rx="{r}" ry="{r*.37}" fill="none" stroke="{color}" stroke-width="2" stroke-dasharray="2 5"/>' for r,color in [(330,'#516071'),(316,'#72849a'),(302,'#445363'),(288,'#738497'),(274,'#354b60'),(260,'#5d7282'),(246,'#6a8190')])
yards=''.join(f'<path d="M{x} 146v88" stroke="#d7eadb" stroke-opacity=".5"/>' for x in range(510,800,28))
svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="400" viewBox="0 0 1000 400"><defs><radialGradient id="night"><stop stop-color="#2b4558"/><stop offset="1" stop-color="#090f18"/></radialGradient><linearGradient id="roof" x2="0" y2="1"><stop stop-color="#718290"/><stop offset=".5" stop-color="#273645"/><stop offset="1" stop-color="#101a26"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="7"/></filter></defs><rect width="1000" height="400" fill="url(#night)"/><ellipse cx="650" cy="190" rx="380" ry="166" fill="#6b9cc7" opacity=".15" filter="url(#glow)"/><ellipse cx="650" cy="190" rx="370" ry="152" fill="url(#roof)" stroke="#9eafbd" stroke-opacity=".6"/><ellipse cx="650" cy="190" rx="342" ry="132" fill="#101924" stroke="#dbeaff" stroke-width="3"/>{seats}<ellipse cx="650" cy="190" rx="237" ry="94" fill="#172c30" stroke="#f2384f" stroke-width="3"/><rect x="490" y="141" width="320" height="98" rx="3" fill="#225441" stroke="#c5ddd2"/><path d="M490 190h320" stroke="#d7eadb" stroke-opacity=".35"/>{yards}<path d="M510 141v98M790 141v98" stroke="#edf7ec" stroke-width="2"/><ellipse cx="650" cy="190" rx="17" ry="13" fill="none" stroke="#dcead8"/><path d="M625 224l28-29 49 0" stroke="#eff0b0" stroke-width="2" fill="none" stroke-dasharray="5 4"/><path d="M696 190l8 5-8 5" fill="none" stroke="#eff0b0" stroke-width="2"/><g fill="#e9f4ff"><rect x="457" y="85" width="80" height="4" rx="2"/><rect x="762" y="85" width="80" height="4" rx="2"/><rect x="457" y="291" width="80" height="4" rx="2"/><rect x="762" y="291" width="80" height="4" rx="2"/></g></svg>'''
(p/'stadium.svg').write_text(svg)
h=(p/'index.html').read_text().replace('Your weekly game plan.','See the whole field.').replace('Tied score\'','Tied score\'')
h=h.replace("diff===0?'Tied score'", "a===0&&b===0?'No points recorded':diff===0?'Tied score'")
(p/'index.html').write_text(h)
j=(p/'binocular.js').read_text().replace("function setView(view){currentView=view;render()}","function setView(view){currentView=view;render();window.scrollTo({top:0,behavior:'instant'})}")
(p/'binocular.js').write_text(j)
